<?php $title = 'Configuración de uniformes'; $subtitle = 'Descripción que utiliza Gemini para evaluar los incumplimientos.'; $section = '/uniformes'; $canEdit = auth()->user()->inGroup('superadmin') || in_array($company['rol'], ['admin', 'superadmin'], true); ?>
<?= $this->extend('admin/layout') ?><?= $this->section('content') ?>
<?php foreach ($rows as $row): ?><section class="card uniform-card"><div class="card-heading"><h2><?= esc($row['nombre']) ?></h2><span class="badge"><?= in_array($row['activo'], [true, 1, '1', 't', 'true'], true) ? 'Activo' : 'Inactivo' ?></span></div><form method="post" action="<?= site_url('admin/uniformes/' . (int) $row['id']) . '?empresa=' . (int) $company['id'] ?>"><?= csrf_field() ?><label for="descripcion-<?= (int) $row['id'] ?>">Descripción del uniforme</label><textarea id="descripcion-<?= (int) $row['id'] ?>" name="descripcion" rows="7" maxlength="10000" required <?= $canEdit ? '' : 'readonly' ?>><?= esc($row['descripcion']) ?></textarea><p class="muted">Los cambios se aplicarán a los próximos análisis de esta empresa.</p><?php if ($canEdit): ?><button type="submit" class="button">Guardar descripción</button><?php else: ?><p class="muted">Tu asociación con esta empresa permite únicamente consultar la configuración.</p><?php endif ?></form></section><?php endforeach ?>
<?php if (! $rows): ?><section class="card empty">No hay uniformes configurados para esta empresa.</section><?php endif ?>
<?= $this->endSection() ?>
